/**
 * Signs release builds with Chatter's own key, when one is provided.
 *
 * `android/` is generated by `expo prebuild`, so the signing setup lives here
 * rather than in android/app/build.gradle, where the next prebuild would wipe
 * it. The key never enters the repository: Gradle reads it from environment
 * variables at build time, which the release workflow fills from GitHub
 * secrets (see .github/workflows/mobile-release.yml):
 *
 *   CHATTER_UPLOAD_STORE_FILE      path to the .jks keystore
 *   CHATTER_UPLOAD_STORE_PASSWORD  the keystore's password
 *   CHATTER_UPLOAD_KEY_ALIAS       the key's alias inside it
 *   CHATTER_UPLOAD_KEY_PASSWORD    the key's password
 *
 * Without them a release build is signed with the debug key, as before, so a
 * local `assembleRelease` still works — but it cannot update an install signed
 * with the real key, and must never be handed out.
 */
const { withAppBuildGradle } = require("expo/config-plugins");

const MARK = "// chatter: release signing";

const SIGNING_CONFIG = `
        ${MARK}
        release {
            def storePath = System.getenv("CHATTER_UPLOAD_STORE_FILE")
            if (storePath) {
                storeFile file(storePath)
                storePassword System.getenv("CHATTER_UPLOAD_STORE_PASSWORD")
                keyAlias System.getenv("CHATTER_UPLOAD_KEY_ALIAS")
                keyPassword System.getenv("CHATTER_UPLOAD_KEY_PASSWORD")
            }
        }`;

/** The edit itself, on build.gradle's text; applying it twice changes nothing. */
function applyReleaseSigning(gradle) {
  if (gradle.includes(MARK)) return gradle;

  // A release signing config beside the debug one.
  const debugBlock = /(signingConfigs\s*\{\s*debug\s*\{[^}]*\})/;
  if (!debugBlock.test(gradle)) throw new Error("withReleaseSigning: no signingConfigs.debug block to extend");
  gradle = gradle.replace(debugBlock, `$1${SIGNING_CONFIG}`);

  // The release build type uses it when a key was provided, else debug.
  const releaseSigning = /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/;
  if (!releaseSigning.test(gradle)) throw new Error("withReleaseSigning: no release signingConfig to replace");
  return gradle.replace(
    releaseSigning,
    `$1signingConfig System.getenv("CHATTER_UPLOAD_STORE_FILE") ? signingConfigs.release : signingConfigs.debug`,
  );
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (mod) => {
    mod.modResults.contents = applyReleaseSigning(mod.modResults.contents);
    return mod;
  });
};
module.exports.applyReleaseSigning = applyReleaseSigning;
